//===--- CppVerifyVersion.h - cpp-verify and backend versions -------------===//
#ifndef LLVM_CLANG_VERIFY_DRIVER_CPPVERIFYVERSION_H
#define LLVM_CLANG_VERIFY_DRIVER_CPPVERIFYVERSION_H

#include "llvm/ADT/StringRef.h"
#include "llvm/Support/raw_ostream.h"

namespace clang {
namespace verify {

/// The Lean toolchain every generated Lean project pins.
inline constexpr llvm::StringLiteral LeanToolchain = "leanprover/lean4:v4.35.0";

/// The toolchains earlier releases pinned. A project that pins one was
/// generated by such a release, and is moved to the current pin.
inline constexpr llvm::StringLiteral EarlierLeanToolchains[] = {
    "leanprover/lean4:v4.32.2"};

/// The oldest and newest cvc5 releases the test suite runs with: CI tests
/// the release build with one and the assertions build with the other.
inline constexpr llvm::StringLiteral CVC5OldestTestedVersion = "1.1.2";
inline constexpr llvm::StringLiteral CVC5NewestTestedVersion = "1.4.2";

/// Prints cpp-verify's version, the LLVM release it is built on, and each
/// verification backend: the linked Z3, and the cvc5 and Lean programs a
/// verification run would find on PATH.
void printVersion(llvm::raw_ostream &OS);

} // namespace verify
} // namespace clang

#endif
